 "content": "from collections import deque

def transform(grid):
    a=[row[:] for row in grid]
    R,C=len(a),len(a[0])
    # Each 5-shaped enclosure has one missing cell in its top side. Fill its
    # interior with 2, and extend the opening outward to the nearest canvas edge.
    seen=set()
    for r in range(R):
        for c in range(C):
            if a[r][c]!=5 or (r,c) in seen: continue
            comp=[]; q=[(r,c)]; seen.add((r,c))
            while q:
                x,y=q.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(x+dx,y+dy)
                    if 0<=z[0]<R and 0<=z[1]<C and a[z[0]][z[1]]==5 and z not in seen:
                        seen.add(z); q.append(z)
            r0=min(x for x,y in comp); r1=max(x for x,y in comp)
            c0=min(y for x,y in comp); c1=max(y for x,y in comp)
            # interior
            for x in range(r0+1,r1):
                for y in range(c0+1,c1):
                    if a[x][y]==0: a[x][y]=2
            # missing top-border pixel is the exit; connect it outwards, in
            # the direction of the opening's horizontal side extension.
            missing=[y for y in range(c0,c1+1) if a[r0][y]!=5]
            if missing:
                y=missing[0]
                # Exit to the left edge, as demonstrated by the opened enclosure.
                for k in range(0,y):
                    if a[r0-1][k]==0: a[r0-1][k]=2
                if r0>0 and a[r0-1][y]==0: a[r0-1][y]=2
                if a[r0][y]==0: a[r0][y]=2
    return a
